export async function POST(req: NextRequest) {
  try {
    const { user, profile } = await getUserAndProfile()
    if (!user || !profile) {
      return NextResponse.json({ error: 'No autorizado' }, { status: 401 })
    }

    const body = await req.json()
    const {
      action = 'confirm',
      planId,
      billingPeriod = 'monthly',
      paymentIntentId,
      isTesterBypass,
    } = body

    // Acción 1: Inicializar sesión de pago con Stripe
    if (action === 'intent') {
      if (!planId || typeof planId !== 'string') {
        return NextResponse.json({ error: 'El ID del plan es obligatorio' }, { status: 400 })
      }
      const intentResult = await createPlanPaymentIntent(profile.id, planId, billingPeriod)
      if (!intentResult.success) {
        return NextResponse.json(
          { error: intentResult.error || 'Error al inicializar la pasarela de pago' },
          { status: 400 }
        )
      }
      return NextResponse.json({ ...intentResult })
    }

    // Acción 2: Confirmar suscripción (Stripe confirmado, tester bypass o plan gratuito)
    if (!paymentIntentId && (!planId || typeof planId !== 'string')) {
      return NextResponse.json({ error: 'El ID del plan es obligatorio' }, { status: 400 })
    }

    if (!paymentIntentId && !isTesterBypass) {
      const result = await confirmPlanPayment(profile.id, planId, billingPeriod)
      if (!result.success) {
        const legacyResult = await updateOwnerPlan(profile.id, planId)
        if (!legacyResult.success) {
          return NextResponse.json(
            { error: result.error || legacyResult.error || 'Error al actualizar el plan' },
            { status: 400 }
          )
        }
        return NextResponse.json({ success: true, updatedPlan: legacyResult.updatedPlan })
      }
      return NextResponse.json({ success: true, updatedPlan: result.updatedPlan })
    }

    const result = await confirmPlanPayment(
      profile.id,
      planId,
      billingPeriod,
      paymentIntentId,
      isTesterBypass
    )

    if (!result.success) {
      return NextResponse.json({ error: result.error || 'Error al confirmar el plan' }, { status: 400 })
    }

    return NextResponse.json({
      success: true,
      updatedPlan: result.updatedPlan,
      isTesterBypass: result.isTesterBypass,
    })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Error al procesar el plan'
    console.error('[api/owner/plans] POST Error:', message)
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

