import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { createAdminClient } from '@/lib/supabase/admin'
import crypto from 'crypto'
import { redis } from '@/lib/redis'
import { getRoomNameFor } from '@/lib/video-provider'
import { TERMINAL_APPOINTMENT_STATUSES } from '@/types'

// ── JWT Helpers ──────────────────────────────────────────────────────────────

function base64UrlEncode(input: string | Buffer): string {
  const buf = typeof input === 'string' ? Buffer.from(input) : input
  return buf.toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
}

/** Sign a JWT using HS256 (symmetric secret — used for Jitsi Local) */
function signJwtHS256(payload: Record<string, unknown>, secret: string): string {
  const header  = { alg: 'HS256', typ: 'JWT' }
  const enc     = (o: unknown) => base64UrlEncode(JSON.stringify(o))
  const data    = `${enc(header)}.${enc(payload)}`
  const sig     = crypto.createHmac('sha256', secret).update(data).digest()
  return `${data}.${base64UrlEncode(sig)}`
}

/** Sign a JWT using RS256 (RSA private key — required for JaaS / 8x8.vc) */
function signJwtRS256(
  payload: Record<string, unknown>,
  privateKeyPem: string,
  kid: string
): string {
  const header  = { alg: 'RS256', kid, typ: 'JWT' }
  const enc     = (o: unknown) => base64UrlEncode(JSON.stringify(o))
  const data    = `${enc(header)}.${enc(payload)}`
  const signer  = crypto.createSign('RSA-SHA256')
  signer.update(data)
  const sig     = signer.sign(privateKeyPem)
  return `${data}.${base64UrlEncode(sig)}`
}

/**
 * Resolve the RSA private key from environment variables for JaaS 8x8 Cloud.
