import { useState, useEffect, useCallback } from 'react'
import { createClient, getCleanChannel } from '@/lib/supabase/client'
import { Notification } from '@/hooks/useNotifications'

export function useNotificationsHistory(profileId: string) {
  const [allNotifications, setAllNotifications] = useState<Notification[]>([])
  const [loading, setLoading] = useState(true)

  const fetchAllNotifications = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/owner/notifications')
      const data = await res.json()
      if (res.ok && Array.isArray(data.notifications)) {
        setAllNotifications(data.notifications)
      }
    } catch (e) {
      console.error('Error fetching notification history:', e)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    if (!profileId) return

    fetchAllNotifications()

    const supabase = createClient()
    const instanceId = Math.random().toString(36).substring(2, 8)
    const channel = getCleanChannel(supabase, `realtime_notifications_history:${profileId}:${instanceId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'notifications',
          filter: `recipient_id=eq.${profileId}`,
        },
        (payload) => {
          if (payload.eventType === 'INSERT') {
            const newNotif = payload.new as Notification
            setAllNotifications(prev => [newNotif, ...prev.filter(n => n.id !== newNotif.id)])
          } else if (payload.eventType === 'UPDATE') {
            const updated = payload.new as Notification
            setAllNotifications(prev => prev.map(n => n.id === updated.id ? updated : n))
          } else if (payload.eventType === 'DELETE') {
            const oldId = (payload.old as { id: string })?.id
            if (oldId) {
              setAllNotifications(prev => prev.filter(n => n.id !== oldId))
            }
          }
        }
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }, [fetchAllNotifications, profileId])

  return {
    allNotifications,
    setAllNotifications,
    loading,
    fetchAllNotifications,
  }
}

