import { isSystemMessage } from './system-messages'

/** Minimum shape a message must have to be groupable. The chat thread's
 *  `MessageRow` is a superset (includes `sender_role`, `attachment_path`,
 *  `read_by_recipient`) — the generic preserves those fields end-to-end. */
export type GroupableMessage = {
  id:                string
  sender_profile_id: string
  body:              string
  created_at:        string
  profiles:          { full_name: string } | null
}

export type Burst<M extends GroupableMessage = GroupableMessage> = {
  senderId:   string
  senderName: string | null
  isMine:     boolean
  isSystem:   boolean
  messages:   M[]
}

export type DayGroup<M extends GroupableMessage = GroupableMessage> = {
  date:   string
  bursts: Burst<M>[]
}

/** Two consecutive messages from the same sender are visually merged into
 *  one bubble stack as long as they fall within this window. */
export const BURST_GAP_MS = 5 * 60 * 1000

/** Human-friendly label for the day-divider row in the thread. */
export function formatDayLabel(iso: string): string {
  const d = new Date(iso)
  const today = new Date()
  const yesterday = new Date(today); yesterday.setDate(today.getDate() - 1)
  if (d.toDateString() === today.toDateString())     return 'Hoy'
  if (d.toDateString() === yesterday.toDateString()) return 'Ayer'
  return d.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' })
}

/** Groups a flat, time-ordered message list into day buckets and
 *  same-sender "bursts" (consecutive messages within BURST_GAP_MS).
 *
 *  Pure & immutable: every iteration produces a new DayGroup or replaces
 *  the last burst with `{...spread, messages:[...]}`. Safe to call from a
 *  `useMemo` and to share across renders / strict-mode double-runs. */
export function groupMessages<M extends GroupableMessage>(
  messages: M[],
  myProfileId: string,
): DayGroup<M>[] {
  const days: DayGroup<M>[] = []
  for (const msg of messages) {
    const dateLabel  = formatDayLabel(msg.created_at)
    const lastDay    = days[days.length - 1]
    const onSameDay  = lastDay?.date === dateLabel

    const isMine     = msg.sender_profile_id === myProfileId
    const lastBurst  = onSameDay ? lastDay.bursts[lastDay.bursts.length - 1] : undefined
    const lastMsg    = lastBurst?.messages[lastBurst.messages.length - 1]
    const sameSender = lastBurst?.senderId === msg.sender_profile_id
    const closeInTime = lastMsg
      ? new Date(msg.created_at).getTime() - new Date(lastMsg.created_at).getTime() < BURST_GAP_MS
      : false

    if (onSameDay && lastBurst && sameSender && closeInTime) {
      const updatedBurst: Burst<M> = { ...lastBurst, messages: [...lastBurst.messages, msg] }
      const updatedDay:   DayGroup<M> = {
        ...lastDay,
        bursts: [...lastDay.bursts.slice(0, -1), updatedBurst],
      }
      days[days.length - 1] = updatedDay
      continue
    }

    const newBurst: Burst<M> = {
      senderId:   msg.sender_profile_id,
      senderName: msg.profiles?.full_name ?? null,
      isMine,
      isSystem:   isSystemMessage(msg.body),
      messages:   [msg],
    }

    if (onSameDay) {
      days[days.length - 1] = { ...lastDay, bursts: [...lastDay.bursts, newBurst] }
    } else {
      days.push({ date: dateLabel, bursts: [newBurst] })
    }
  }
  return days
}

