/**
 * Publishes a medical record adhering to ADR-5 invariants:
 * 1. Atomic one-way state transition (`.not('is_published', 'is', true)`).
 * 2. Idempotent prescription generation linked by `source_record_id`.
 * 3. Notification dispatch to pet owner (RECORD_PUBLISHED and PRESCRIPTION_READY).
 */
export async function publishRecord({
  admin,
  recordId,
  profile,
  contentPatch,
}: PublishRecordParams): Promise<PublishRecordResult> {
  // 1. Pre-fetch existing record for authorization and state check
  const { data: existingRecord, error: lookupErr } = await admin
    .from('medical_records')
    .select('*')
    .eq('id', recordId)
    .maybeSingle()

  if (lookupErr || !existingRecord) {
    return { ok: false, error: 'Informe no encontrado', status: 404 }
  }

  if (existingRecord.vet_id !== profile.id && profile.role !== 'superadmin') {
    return { ok: false, error: 'No tienes permisos para modificar este informe', status: 403 }
  }

  // Idempotent: already published
  if (existingRecord.is_published === true) {
    return { ok: true, record: existingRecord, alreadyPublished: true }
  }

  // 2. Atomic publish update
  const basePublishPatch: Record<string, unknown> = {
    ...(contentPatch ?? {}),
    is_published: true,
    published_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  }

  const attemptPublish = (payload: Record<string, unknown>) =>
    admin
      .from('medical_records')
      .update(payload)
      .eq('id', recordId)
      .not('is_published', 'is', true)
      .select()

  let { data: publishedRows, error: publishError } = await attemptPublish(basePublishPatch)

  if (publishError && (publishError.code === 'PGRST204' || publishError.code === '42703')) {
    console.warn('[publishRecord] published_at no existe todavía (migración 0001 pendiente); publicando sin timestamp.')
    const withoutPublishedAt = { ...basePublishPatch }
    delete withoutPublishedAt.published_at
    ;({ data: publishedRows, error: publishError } = await attemptPublish(withoutPublishedAt))
  }

  if (publishError) {
    return { ok: false, error: publishError.message, status: 400 }
