/**
 * Formatea la hora de una cita de manera contextual:
 * - Citas presenciales: siempre fijas en la hora de la clínica (default 'Europe/Madrid').
 * - Videoconsultas: si el huso del usuario difiere del de la clínica, muestra hora dual (ej. "10:30 (Tu hora) · 11:30 (Hora clínica)").
 */
export function formatAppointmentSlot(
  appointmentDate: string | null | undefined,
  appointmentTime: string | null | undefined,
  options: FormatAppointmentSlotOptions = {}
): string {
  if (!appointmentTime) return ''
  const cleanTime = appointmentTime.slice(0, 5)
  const modality = options.modality || 'presencial'
  const clinicTz = options.clinicTimeZone || 'Europe/Madrid'
  const clinicLabel = options.clinicLabel || 'Hora clínica'

  // Presencial: se ancla siempre a la hora física de la clínica
  if (modality === 'presencial') {
    return cleanTime
  }

  // Videoconsulta: verificar si el huso del usuario difiere del de la clínica
  const userTz =
    options.userTimeZone ||
    (typeof Intl !== 'undefined' ? Intl.DateTimeFormat().resolvedOptions().timeZone : clinicTz)

  if (!userTz || userTz === clinicTz || !appointmentDate) {
    return cleanTime
  }

  const slotUtc = convertWallClockToUTC(appointmentDate, cleanTime, clinicTz)
  if (!slotUtc) return cleanTime

  const userTime = formatTime(slotUtc, { timeZone: userTz })
  if (!userTime || userTime === cleanTime) {
    return cleanTime
  }

  return `${userTime} (Tu hora) · ${cleanTime} (${clinicLabel})`
}
