// ── POST — same auth/guard/generation pipeline as ../route.ts's POST, but
// streams the main LLM generation attempt to the client as SSE frames
// instead of waiting for the full reply. Preview-only: what gets persisted
// is still exactly what generateAndPersistDraft() validates via
// parseDraft() — this route adds no new write path.
export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id: appointmentId } = await params
  const auth = await authorizeVet(appointmentId)
  if (isAuthError(auth)) return auth
  const { admin, profileId } = auth

  const rateCheck = await checkAiRateLimit('draft', profileId)
  if (rateCheck.limited) {
    if (rateCheck.reason === 'redis_unavailable') {
      return jsonResponse({ error: 'Servicio de IA no disponible temporalmente' }, 503)
    }
    return jsonResponse(
      { error: `Límite de solicitudes excedido. Intenta de nuevo en ${rateCheck.retryAfter ?? 60}s.` },
      429,
    )
  }

  // Same 'consumed' sticky pre-check as the non-streaming POST — a consumed
  // draft already produced a medical record; regenerating over it (streamed
  // or not) would re-enable the confirm path and risk a duplicate record.
  const { data: existingDraft, error: existingErr } = await admin
    .from('consultation_drafts')
    .select('status')
    .eq('appointment_id', appointmentId)
    .maybeSingle()
