export async function PATCH(req: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return NextResponse.json({ error: 'No autorizado' }, { status: 401 })

  const admin = createAdminClient()
  const { data: profile } = await admin.from('profiles').select('id').eq('user_id', user.id).single()
  if (!profile) return NextResponse.json({ error: 'Perfil no encontrado' }, { status: 403 })

  const body = await req.json() as { id?: string; markAll?: boolean }

  if (body.markAll) {
    const { error } = await admin
      .from('notifications')
      .update({ is_read: true })
      .eq('recipient_id', profile.id)
      .eq('is_read', false)

    if (error) {
      console.error('[notifications PATCH] Failed to mark all as read:', error.message)
      return NextResponse.json({ error: 'No se pudieron actualizar las notificaciones' }, { status: 500 })
    }
    return NextResponse.json({ ok: true })
  }

  if (!body.id) {
    return NextResponse.json({ error: 'id o markAll es requerido' }, { status: 400 })
  }

  // Anti-BOLA: verify notification belongs to recipient profile.id
  const { error } = await admin
    .from('notifications')
    .update({ is_read: true })
    .eq('id', body.id)
    .eq('recipient_id', profile.id)

  if (error) {
    console.error('[notifications PATCH] Failed to mark as read:', error.message)
    return NextResponse.json({ error: 'No se pudo actualizar la notificación' }, { status: 500 })
