/**
 * Versión batch: inserta múltiples notificaciones respetando notifications_enabled de cada destinatario.
 * Útil para alertas de emergencia que van a varios vets.
 *
 * @param admin - Admin Supabase client
 * @param payloads - Array de payloads a insertar
 * @returns Número de notificaciones insertadas correctamente
 */
export async function insertNotifications(
  admin: SupabaseClient,
  payloads: NotificationPayload[]
): Promise<number> {
  if (payloads.length === 0) return 0

  // Obtener todos los destinatarios únicos de una sola query
  const recipientIds = [...new Set(payloads.map(p => p.recipient_id))]
  const { data: profiles } = await admin
    .from('profiles')
    .select('id, notifications_enabled')
    .in('id', recipientIds)

  const enabledIds = new Set(
    (profiles ?? [])
      .filter(p => p.notifications_enabled !== false)
      .map(p => p.id)
  )

  const toInsert = payloads
    .filter(p => enabledIds.has(p.recipient_id))
    .map(p => ({
      recipient_id: p.recipient_id,
      sender_id:    p.sender_id ?? null,
      type:         p.type,
      title:        stripEmojis(p.title),
      body:         stripEmojis(p.body),
      action_url:   p.action_url ?? null,
      metadata:     p.metadata ?? {},
    }))

  if (toInsert.length === 0) return 0

  const { error } = await admin.from('notifications').insert(toInsert)
  if (error) {
    console.error('[insertNotifications] Error en batch insert:', error.message)
    return 0
  }

  return toInsert.length
}
