interface FetchResult { status:number; ms:number; bytes:number; headers:Record<string,string|null> }

async function tf(url: string, opts?: RequestInit): Promise<FetchResult> {
  const t = Date.now()
  try {
    const r = await fetch(url, { ...opts, signal: AbortSignal.timeout(10_000) })
    const buf = await r.arrayBuffer()
    return {
      status: r.status, ms: Date.now()-t, bytes: buf.byteLength,
      headers: {
        csp: r.headers.get('content-security-policy'),
        xframe: r.headers.get('x-frame-options'),
        xcto: r.headers.get('x-content-type-options'),
        rateLimit: r.headers.get('x-ratelimit-remaining'),
        retryAfter: r.headers.get('retry-after'),
      }
    }
  } catch { return { status:0, ms:Date.now()-t, bytes:0, headers:{} } }
}

function pct(arr: number[], p: number) {
  const s = [...arr].sort((a,b)=>a-b)
  return s[Math.max(0, Math.ceil(p/100*s.length)-1)]
}
function statsStr(times: number[]) {
  if (!times.length) return 'sin datos'
  const sorted = [...times].sort((a,b)=>a-b)
  const mean = times.reduce((a,b)=>a+b,0)/times.length
  return `p50:${pct(times,50)}ms p95:${pct(times,95)}ms p99:${pct(times,99)}ms mean:${mean.toFixed(0)}ms max:${sorted[sorted.length-1]}ms (n=${times.length})`
}

function sleep(ms:number) { return new Promise(r=>setTimeout(r,ms)) }
