  const { data: profile } = await admin
    .from('profiles')
    .select('id, role')
    .eq('user_id', userId)
    .maybeSingle()

  if (!profile) return { authorized: false, error: 'Perfil no encontrado' }

  if (profile.role === 'superadmin') {
    return { authorized: true, profile }
  }

  const { data: conversation } = await admin
    .from('conversations')
    .select('owner_id, vet_id')
    .eq('id', conversationId)
    .maybeSingle()

  if (!conversation) return { authorized: false, error: 'Conversación no encontrada' }

  const isParticipant = conversation.owner_id === profile.id || conversation.vet_id === profile.id
  if (!isParticipant) {
    return { authorized: false, error: 'Acceso denegado a esta conversación' }
  }

  return { authorized: true, profile }
}
