import { NextRequest, NextResponse } from 'next/server'
import { createAdminClient } from '@/lib/supabase/admin'

export const dynamic = 'force-dynamic'

/**
 * POST /api/admin/cleanup-drafts
 *
 * Endpoint de administración / orquestador cron para ejecutar la limpieza
 * de borradores atascados en `generating` cuyo último heartbeat (`updated_at`)
 * supere los 10 minutos.
 *
 * Autenticación: Requiere la cabecera `Authorization: Bearer <CRON_SECRET>`
 * o una sesión activa con rol `superadmin`.
 */
export async function POST(req: NextRequest) {
  try {
    const authHeader = req.headers.get('authorization')
    const cronSecret = process.env.CRON_SECRET

    let isAuthorized = false

    if (cronSecret && authHeader === `Bearer ${cronSecret}`) {
      isAuthorized = true
    }

    if (!isAuthorized) {
      // Verificar si el usuario que llama tiene rol superadmin
      const { createClient } = await import('@/lib/supabase/server')
      const supabase = await createClient()
      const { data: { user } } = await supabase.auth.getUser()
      if (user) {
        const admin = createAdminClient()
        const { data: profile } = await admin.from('profiles').select('role').eq('user_id', user.id).single()
        if (profile?.role === 'superadmin') {
          isAuthorized = true
        }
      }
    }

    if (!isAuthorized) {
      return NextResponse.json({ error: 'No autorizado' }, { status: 401 })
    }

    const admin = createAdminClient()

    // Invocar la función SQL segura que usa updated_at (heartbeat)
    const { data, error } = await admin.rpc('cleanup_stuck_consultation_drafts')

    if (error) {
      // Fallback manual en código por si la RPC no existe aún
      const tenMinutesAgo = new Date(Date.now() - 10 * 60 * 1000).toISOString()
      const { data: fallbackData, error: fallbackErr } = await admin
        .from('consultation_drafts')
        .update({ status: 'failed', updated_at: new Date().toISOString() })
        .eq('status', 'generating')
        .lt('updated_at', tenMinutesAgo)
        .select('appointment_id')

      if (fallbackErr) {
        return NextResponse.json({ error: fallbackErr.message }, { status: 500 })
      }

      return NextResponse.json({
        ok: true,
        cleaned: fallbackData?.length ?? 0,
        mode: 'fallback_query'
      })
    }

    return NextResponse.json({
      ok: true,
      cleaned: data,
      mode: 'rpc_heartbeat'
    })
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Error interno del servidor'
    return NextResponse.json({ error: msg }, { status: 500 })
  }
}

