import { z } from 'zod'
import { reconcileExpiredAppointments } from '@/lib/utils/appointments-reconciliation'

import { timeToMinutes, getLocalDateString, getLocalTimeString } from '@/lib/utils/time'

const querySchema = z.object({
  vetId: z.string().uuid('vetId debe ser un UUID válido'),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'date debe tener el formato YYYY-MM-DD')
})

// GET /api/appointments/slots?vetId=X&date=YYYY-MM-DD
// Returns: { slots: { time: string; available: boolean }[] }
export async function GET(req: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return NextResponse.json({ error: 'No autorizado' }, { status: 401 })

  const searchParams = req.nextUrl.searchParams
  const vetId = searchParams.get('vetId') ?? searchParams.get('vet_id')
  const date = searchParams.get('date')

  const parsed = querySchema.safeParse({ vetId, date })
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.issues[0]?.message || 'Parámetros inválidos' }, { status: 400 })
  }
  const { vetId: validatedVetId, date: validatedDate } = parsed.data

  const admin = createAdminClient()

  const { data: vetProfile } = await admin
    .from('profiles')
    .select('id, timezone')
    .eq('id', validatedVetId)
    .maybeSingle()

  const clinicTimeZone = (vetProfile as any)?.timezone || 'Europe/Madrid'

  await reconcileExpiredAppointments(admin, { vetId: validatedVetId, timeZone: clinicTimeZone })
  const dayOfWeek = new Date(validatedDate + 'T12:00:00').getDay()

  const { data: schedules } = await admin
    .from('clinic_schedules')
