  const { data: appt } = await admin.from('appointments').select('id, vet_id').eq('id', appointmentId).single()
  if (!appt) return NextResponse.json({ error: 'Cita no encontrada' }, { status: 404 })

  if (appt.vet_id !== profile.id) {
    return NextResponse.json({ error: 'Sin permisos para el borrador de esta cita' }, { status: 403 })
  }

  return { admin, profileId: profile.id }
}

