import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { createAdminClient } from '@/lib/supabase/admin'
import { redis } from '@/lib/redis'
import {
  DEEPGRAM_GRANT_URL, DEEPGRAM_TOKEN_TTL_SECONDS,
  MAX_TOKEN_GRANTS_PER_APPOINTMENT_PER_HOUR, MAX_TOKEN_GRANTS_PER_APPOINTMENT_PER_DAY,
  DEEPGRAM_GRANT_CACHE_MIN_REMAINING_SECONDS,
} from '@/lib/stt/deepgram-config'
import { TERMINAL_APPOINTMENT_STATUSES } from '@/types'

interface CachedGrant {
  access_token: string
  // Absolute epoch ms — NOT a duration, so remaining lifetime is always
  // computed against the moment of the read, never the moment of the write.
  expires_at: number
}

function grantCacheKey(appointmentId: string, profileId: string): string {
  return `deepgram:grant:${appointmentId}:${profileId}`
}

// Deliberate runtime shape guard for a value that already parsed as valid
// JSON — an old/corrupt cached payload (schema drift, partial write) must be
// treated as an explicit cache miss, not fall through to remainingSeconds
// math and rely on NaN-comparison luck to fail safe.
function isValidCachedGrant(value: unknown): value is CachedGrant {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as CachedGrant).access_token === 'string' &&
    (value as CachedGrant).access_token.length > 0 &&
    Number.isFinite((value as CachedGrant).expires_at)
  )
}

// Missing-table/relation sentinel, shared with the count + insert queries
// below. PostgREST reports a table absent from its schema cache as
// PGRST205, not the underlying Postgres 42P01 (undefined_table) — same
// convention as src/app/api/consultations/[id]/transcript/route.ts. Both are
// checked so the breaker fails open regardless of which layer surfaces it.
function isMissingRelationError(code: string | undefined): boolean {
  return code === '42P01' || code === 'PGRST205'
}

