export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return NextResponse.json({ error: 'No autorizado' }, { status: 401 })

  const admin = createAdminClient()

  // Get user profile
  const { data: profile } = await admin
    .from('profiles')
    .select('id, role')
    .eq('user_id', user.id)
    .single()

  if (!profile) {
    return NextResponse.json({ error: 'Perfil no encontrado' }, { status: 404 })
  }

  const { rating, comment, is_anonymous, rated_by } = await req.json()

  if (!rating || rating < 1 || rating > 5)
    return NextResponse.json({ error: 'Calificación inválida (1–5)' }, { status: 400 })
  if (!rated_by || !['owner', 'vet'].includes(rated_by))
    return NextResponse.json({ error: 'rated_by inválido' }, { status: 400 })

  // Verify appointment exists
  const { data: appt } = await admin.from('appointments')
    .select('id, status, owner_id, vet_id')
    .eq('id', id)
    .single()

  if (!appt) return NextResponse.json({ error: 'Cita no encontrada' }, { status: 404 })

  // Authorization check
  if (rated_by === 'owner') {
    if (profile.role !== 'pet_owner' || appt.owner_id !== profile.id) {
      return NextResponse.json({ error: 'No autorizado para calificar esta cita' }, { status: 403 })
    }
  } else if (rated_by === 'vet') {
    if (profile.role !== 'veterinarian') {
      return NextResponse.json({ error: 'No autorizado para calificar esta cita' }, { status: 403 })
    }
    // Check if they are the assigned vet
    if (appt.vet_id !== profile.id) {
      return NextResponse.json({ error: 'No autorizado para calificar esta cita' }, { status: 403 })
    }
  }

  // M-5: Only allow rating completed appointments
  if (appt.status !== 'completed') {
    return NextResponse.json({ error: 'Solo se pueden calificar citas que hayan sido completadas' }, { status: 400 })
  }

  const { error } = await admin.from('appointment_ratings').upsert({
    appointment_id: id,
    rated_by,
    rating,
    comment:      comment?.trim() || null,
    is_anonymous: Boolean(is_anonymous),
  }, { onConflict: 'appointment_id,rated_by' })

  if (error) return NextResponse.json({ error: error.message }, { status: 400 })

  return NextResponse.json({ ok: true })
}

